<?php
require_once __DIR__ . '/includes/auth.php';
require_admin();
$pageTitle='Log Aktivitas';$activePage='log';$pdo=db();$q=trim($_GET['q']??'');$stmt=$pdo->prepare('SELECT l.*,u.nama,u.role FROM log_kasir l JOIN users u ON u.id=l.user_id WHERE u.nama LIKE ? OR l.aksi LIKE ? OR l.keterangan LIKE ? ORDER BY l.created_at DESC LIMIT 250');$like='%'.$q.'%';$stmt->execute([$like,$like,$like]);$logs=$stmt->fetchAll();
include __DIR__.'/includes/header.php';
?><section class="card"><div class="section-head"><div><h2>Log aktivitas kasir</h2></div></div><form class="search-row" method="get"><input class="input" name="q" value="<?= e($q) ?>" placeholder="Cari pengguna atau aktivitas..."><button class="btn btn-light">Cari</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aktivitas</th><th>Keterangan</th></tr></thead><tbody><?php foreach($logs as $row): ?><tr><td><?= e(date('d/m/Y H:i:s',strtotime($row['created_at']))) ?></td><td><strong><?= e($row['nama']) ?></strong> <span class="badge <?= e($row['role']) ?>"><?= e(ucfirst($row['role'])) ?></span></td><td><?= e($row['aksi']) ?></td><td><?= e($row['keterangan']) ?></td></tr><?php endforeach;if(!$logs): ?><tr><td colspan="4" class="empty">Belum ada aktivitas.</td></tr><?php endif; ?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php'; ?>
